'use strict';
const $ = (q, root = document) => root.querySelector(q);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const course = window.COURSE;
const lessons = [...window.FOUNDATIONS, ...course.lessons];
const exercises = course.exercises;
const tracks = [
  ['node','JS & Node.js','JS','Write clear code and explain the runtime.'],
  ['redis','Redis & caching','R','Fast reads, fresh data, and failure handling.'],
  ['aws','AWS & background jobs','λ','Schedules, queues, retries, and safe delivery.'],
  ['rag','RAG & AI systems','AI','From documents to grounded answers.'],
  ['dsa','Data structures','{}','Arrays, maps, sets, and linked lists.'],
  ['design','System design','↔','Turn requirements into practical architecture.'],
  ['projects','Your project stories','◈','Defend decisions with real evidence.'],
  ['react','React essentials','Re','A focused refresh for frontend questions.']
];
const nav = [['/','◫','Study room'],['/plan','☑','Your study plan'],['/learn','▤','Learning library'],['/practice','⌘','Coding practice'],['/lab','◇','RAG lab'],['/mocks','◎','Mock interviews'],['/videos','▷','Video shelf']];
const storageKey = 'interview-studio-v1';
let state = {done:{},checks:{},scores:{},plan:'sprint'};
let storageAvailable = true;
try { const raw = JSON.parse(localStorage.getItem(storageKey)); if (raw && typeof raw === 'object') { for (const key of ['done','checks','scores']) if(raw[key] && typeof raw[key] === 'object' && !Array.isArray(raw[key])) state[key]=raw[key]; if(['sprint','three','week'].includes(raw.plan))state.plan=raw.plan; } } catch {storageAvailable=false;}
function save(){try{localStorage.setItem(storageKey, JSON.stringify(state));}catch{storageAvailable=false;toast('Your browser could not save progress. Keep this page open.');}}
const total = () => lessons.length + exercises.length + course.mocks.length;
const allIds = () => [...lessons,...exercises,...course.mocks].map(x=>x.id);
const completed = () => allIds().filter(id=>state.done[id]).length;
const percent = () => Math.round(completed()/total()*100);
const trackName = id => tracks.find(t=>t[0]===id)?.[1] || id;
const lessonUrl = id => '#/learn/'+id;
const sectionHead = (title,link='',label='') => `<div class="section-head"><h2>${title}</h2>${link?`<a href="${link}">${label} <span aria-hidden="true">↗</span></a>`:''}</div>`;
const heading = (eyebrow,title,subtitle,extra='') => `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;
const check = (id,label,type='done') => `<label class="check"><input type="checkbox" data-${type}="${esc(id)}" ${state[type][id]?'checked':''}><span>${label}</span></label>`;
const qa = (q,a) => `<details class="question"><summary>${esc(q)}</summary><div class="answer">${a}</div></details>`;
const completion = id => `<div class="completion">${check(id,'I can explain this without looking.')}<span class="card-meta">Be honest. Revisit anything uncertain.</span></div>`;
const plans = {
 sprint:{label:'1-day focus',desc:'About 6 focused hours, plus breaks. Choose this if time is short. Read the core explanations, then practice aloud; the full library is your reference.',days:[
 {title:'01 · Set the foundation',note:'75 minutes · Stay close to what you have built.',items:['resume-stories','node-async']},
 {title:'02 · Cache with confidence',note:'60 minutes · Cache-aside first, then failure modes.',items:['redis-basics','redis-reliability']},
 {title:'03 · Connect the AI pipeline',note:'60 minutes · Sketch both ingestion and querying.',items:['rag-basics','rag-pipeline']},
 {title:'04 · Make jobs reliable',note:'45 minutes · Explain duplicates and worker failures.',items:['aws-jobs']},
 {title:'05 · Code and narrate',note:'60 minutes · Attempt first; open solutions only afterward.',items:['two-sum','reverse-list','linked-list-cycle','longest-substring']},
 {title:'06 · Rehearse the interview',note:'60 minutes · Use Mock 1. Flag weak areas for the final review.',items:['mock-backend']}
 ]},
 three:{label:'3-day plan',desc:'About 4–5 hours a day with breaks. Use explanations first, then retrieve them from memory. Finish one mock each day.',days:[
 {title:'Day 1 · Own the fundamentals',note:'JavaScript, backend APIs, projects and map patterns.',items:['js-foundations','node-async','api-database','resume-stories','dsa-maps','two-sum','valid-anagram','contains-duplicate','mock-backend']},
 {title:'Day 2 · Build reliable systems',note:'Redis, AWS and linked lists; finish with an architecture rehearsal.',items:['redis-basics','redis-reliability','aws-foundations','aws-jobs','dsa-lists','reverse-list','linked-list-cycle','merge-lists','mock-design']},
 {title:'Day 3 · Connect and defend',note:'RAG, system design, React, remaining coding patterns and a project deep dive.',items:['rag-basics','rag-pipeline','rag-quality','system-design','react-refresh','dsa-arrays','stock-profit','longest-substring','mock-projects']}
 ]},
 week:{label:'7-day path',desc:'Around 2–3 hours most days. Make the later sessions active recall, timed coding, and mock interviews rather than repeated reading.',days:[
 {title:'Day 1 · JavaScript and Node',note:'Write small examples and explain every async step.',items:['js-foundations','node-async','api-database']},
 {title:'Day 2 · Map, set, and array patterns',note:'Solve each once unaided and trace edge cases.',items:['dsa-maps','dsa-arrays','two-sum','contains-duplicate','valid-anagram','intersection','stock-profit','move-zeroes','group-anagrams','longest-substring']},
 {title:'Day 3 · Caching and pointers',note:'Connect data structures to cache behavior.',items:['redis-basics','redis-reliability','dsa-lists','reverse-list','middle-list','linked-list-cycle','merge-lists','remove-nth','delete-given-node']},
 {title:'Day 4 · AWS and reliable work',note:'Trace a job through success, duplicate delivery and failure.',items:['aws-foundations','aws-jobs','lru-cache','mock-backend']},
 {title:'Day 5 · RAG end to end',note:'Read all three lessons and run the RAG lab example.',items:['rag-basics','rag-pipeline','rag-quality']},
 {title:'Day 6 · System design and React',note:'Draw architecture before checking the suggested solution.',items:['system-design','react-refresh','mock-design']},
 {title:'Day 7 · Project defense and review',note:'Substantiate your claims, rehearse, and close the remaining gaps.',items:['resume-stories','mock-projects']}
 ]}
};
function itemById(id){return lessons.find(x=>x.id===id)||exercises.find(x=>x.id===id)||course.mocks.find(x=>x.id===id);}
function itemUrl(id){return lessons.some(x=>x.id===id)?lessonUrl(id):exercises.some(x=>x.id===id)?'#/practice/'+id:'#/mocks/'+id;}
function nextItem(){return plans[state.plan].days.flatMap(d=>d.items).map(itemById).find(x=>x&&!state.done[x.id]) || lessons.find(x=>!state.done[x.id]);}
function updateProgress(){ $('#side-progress').innerHTML=`<progress value="${completed()}" max="${total()}" aria-label="Overall preparation progress"></progress><div>${completed()} of ${total()} activities complete</div>`; }
function tabs(){return `<div class="tabs" aria-label="Preparation time">${Object.entries(plans).map(([key,p])=>`<button data-plan="${key}" aria-pressed="${state.plan===key}">${p.label}</button>`).join('')}</div>`;}
function trackCards(){return `<div class="cards">${tracks.map(([id,title,icon,desc])=>{const group=lessons.filter(l=>l.track===id);return `<article class="card"><div class="card-top"><span class="track-icon">${icon}</span><span class="card-meta">${group.length} lessons</span></div><h3><a href="#/learn/track/${id}">${title}</a></h3><p>${desc}</p><hr><a class="arrow-link" href="#/learn/track/${id}">${group.filter(x=>state.done[x.id]).length} / ${group.length} complete <span aria-hidden="true">→</span></a></article>`;}).join('')}</div>`;}
function home(){const next=nextItem();return heading('WELCOME TO YOUR STUDY ROOM','A little more prepared.<br>One topic at a time.','Your focused route through the Shownex technical interview. Learn the concepts, write the code, and explain your decisions.',`<span class="pill">Backend · Node.js · AI systems</span>`)+`<div class="focus-grid"><section class="focus-card"><div class="eyebrow">${next?'YOUR NEXT FOCUS':'YOU COMPLETED YOUR PLAN'}</div><h2>${next?esc(next.title):'Time for one more rehearsal.'}</h2><p>${next?esc(next.summary||next.prompt||next.focus):'Revisit the questions you found difficult, then explain the architecture aloud.'}</p><a class="btn" href="${next?itemUrl(next.id):'#/mocks'}">${next?'Continue preparing':'Choose a mock interview'} <span aria-hidden="true">→</span></a></section><section class="progress-card" aria-label="Preparation progress"><div class="ring" style="--p:${percent()}%"><div class="ring-inner"><strong>${percent()}%</strong><small>COMPLETE</small></div></div><p><strong>${completed()} of ${total()} activities</strong><br>Understanding beats speed.</p></section></div>`+sectionHead('Make time for what matters','#/plan','Open full plan')+tabs()+`<p class="muted">${plans[state.plan].desc}</p><div class="plan-list">${plans[state.plan].days.slice(0,3).map((d,i)=>`<div class="plan-row"><span class="plan-number">${String(i+1).padStart(2,'0')}</span><div><h3><a href="#/plan">${esc(d.title.replace(/^.*? · /,''))}</a></h3><p>${esc(d.note)}</p></div><span class="time">${d.items.filter(x=>state.done[x]).length}/${d.items.length} done</span></div>`).join('')}</div>`+sectionHead('Your learning library','#/learn','Explore all lessons')+trackCards()+sectionHead('Practice the conversation','#/mocks','See all three mocks')+`<div class="two-col"><div class="card"><span class="tag">FOR YOUR INTERVIEW PARTNER</span><h3 style="margin-top:17px">Three different interviews. One clear rubric.</h3><p>Coding and backend fundamentals, architecture and RAG, then project defense. Questions and answer guides are ready for your friend.</p><a class="arrow-link" href="#/mocks">Open the interviewer kit →</a></div><div class="card"><span class="tag">WHY THESE TOPICS?</span><h3 style="margin-top:17px">Prepare for the product context.</h3><p>${esc(course.company.summary)}</p><a class="arrow-link" href="#/context">Read the interview context →</a></div></div>`;}
function plan(){return heading('YOUR STUDY PLAN','A path that fits your time.','Check off a topic after you can explain it. Your choices sync across the plan, lessons, and practice pages.')+tabs()+`<p class="note">${plans[state.plan].desc} Time estimates are guides, not deadlines. If a concept is new, take longer and skip stretch work.</p>`+plans[state.plan].days.map(d=>`<section class="journey-day"><h2>${esc(d.title)}</h2><p class="muted">${esc(d.note)}</p><div class="plan-list">${d.items.map(id=>{const item=itemById(id);if(!item)return '';return `<div class="plan-row"><div>${check(id,'<span class="sr-only">Complete '+esc(item.title)+'</span>')}</div><div><h3><a href="${itemUrl(id)}">${esc(item.title)}</a></h3><p>${lessons.includes(item)?trackName(item.track):exercises.includes(item)?'Coding practice · '+item.pattern:'Mock interview'}</p></div><a href="${itemUrl(id)}" class="time">Open →</a></div>`;}).join('')}</div></section>`).join('');}
function library(track){const selected=tracks.find(t=>t[0]===track);return heading('LEARNING LIBRARY',selected?selected[1]:'Everything, in one place.',selected?selected[3]:'Self-contained lessons, worked examples, and questions to answer aloud. Start with your weak areas or follow the study plan.')+(selected?'<p class="crumb"><a href="#/learn">← All topics</a></p>':trackCards())+sectionHead(selected?'Lessons in this topic':'All lessons')+`<div class="plan-list">${lessons.filter(l=>!track||l.track===track).map((l,i)=>`<div class="plan-row"><span class="plan-number">${state.done[l.id]?'✓':String(i+1).padStart(2,'0')}</span><div><h3><a href="${lessonUrl(l.id)}">${esc(l.title)}</a></h3><p>${esc(l.summary)}</p></div><span class="time">${l.minutes} min · ${esc(trackName(l.track))}</span></div>`).join('')}</div>`;}
function lesson(id){const l=lessons.find(x=>x.id===id);if(!l)return missing();const ordered=lessons.filter(x=>x.track===l.track);const next=ordered[ordered.indexOf(l)+1];return `<div class="crumb"><a href="#/learn">Library</a> / <a href="#/learn/track/${l.track}">${esc(trackName(l.track))}</a></div>`+heading(trackName(l.track).toUpperCase(),esc(l.title),esc(l.summary),`<span class="pill">${l.minutes} min · ${l.priority==='core'?'Core lesson':'Supporting lesson'}</span>`)+`<div class="article-layout"><article class="article">${l.sections.map((s,i)=>`<section id="part-${i}"><h2>${esc(s.title)}</h2>${s.html}</section>`).join('')}<section id="ready"><h2>Can you explain it?</h2><p class="muted">Close the explanation and try these from memory.</p><div class="checks">${l.checks.map((c,i)=>check(l.id+'-'+i,esc(c),'checks')).join('')}</div></section><section id="questions"><h2>Interview questions</h2>${l.questions.map(q=>qa(q.q,esc(q.a))).join('')}</section>${completion(l.id)}<p style="margin-top:25px;margin-bottom:0"><a class="btn" href="${next?lessonUrl(next.id):'#/plan'}">${next?'Next: '+esc(next.title):'Back to your plan'} →</a></p></article><aside class="article-aside"><h3>IN THIS LESSON</h3>${l.sections.map((s,i)=>`<a href="#" data-scroll="part-${i}">${esc(s.title)}</a>`).join('')}<a href="#" data-scroll="ready">Readiness checklist</a><a href="#" data-scroll="questions">Interview questions</a><div class="aside-box"><h3>Say it out loud.</h3><p class="muted">Use a concrete example. Explain the tradeoff. Finish with how you would test it.</p><a href="#/videos">Optional video shelf →</a></div></aside></div>`;}
function exerciseCard(e,full=false){return `<article class="exercise" id="exercise-${e.id}"><div class="exercise-meta"><span class="tag ${e.difficulty.toLowerCase()}">${esc(e.difficulty)}</span><span class="card-meta">${esc(e.pattern)} · ${e.minutes} min</span></div><h2>${full?'':`<a href="#/practice/${e.id}">`}${esc(e.title)}${full?'':'</a>'}</h2><p>${esc(e.prompt)}</p><pre><code>${esc(e.example)}</code></pre>${qa('A nudge, if you need it',esc(e.hint))}${qa('Reveal solution & reasoning',`<pre><code>${esc(e.code)}</code></pre><p>${esc(e.explanation)}</p><p><strong>Complexity:</strong> ${esc(e.complexity)}</p><strong>Test these cases</strong><ul>${e.tests.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`)}${check(e.id,'I solved it and explained the complexity.')}</article>`;}
function practice(id){const ex=exercises.find(e=>e.id===id);if(id&&!ex)return missing();return heading('CODING PRACTICE',ex?esc(ex.title):'Think first. Then write the code.',ex?'Work in your editor. Say the invariant aloud and test the edge cases before opening the solution.':'15 focused problems in JavaScript. Attempt → explain → check. No trees or dynamic programming detour.')+(ex?`<p class="crumb"><a href="#/practice">← All coding problems</a></p>${exerciseCard(ex,true)}`:`<div class="note"><strong>Your 6-step coding routine</strong>Clarify inputs → walk an example → name a baseline → choose a structure → write and trace → explain complexity. Solutions are intentionally hidden.</div><div class="practice-grid">${exercises.map(e=>exerciseCard(e)).join('')}</div>`);}
function mocks(id){const m=course.mocks.find(x=>x.id===id);if(id&&!m)return missing();if(!m)return heading('THE INTERVIEWER KIT','Practice with a person.','Three 60-minute rounds for your friend to run. Each has timed prompts, follow-up questions, expected answers, and a saved scorecard.')+`<div class="note"><strong>For the interviewer</strong>Read the prompt only. Let the candidate clarify, think, and code. Use a follow-up after the first answer. Keep the guide collapsed until you grade. Reserve a separate 10 minutes for feedback.</div><div class="cards">${course.mocks.map((m,i)=>`<article class="card mock-card"><div class="card-top"><span class="track-icon">0${i+1}</span><span class="card-meta">${m.minutes} minutes</span></div><h3>${esc(m.title)}</h3><p>${esc(m.focus)}</p><p class="card-meta">${m.rounds.length} segments · Questions + answer guide</p><a class="btn secondary" href="#/mocks/${m.id}">Start this mock →</a></article>`).join('')}</div>`;
return `<p class="crumb"><a href="#/mocks">← All mock interviews</a></p>`+heading('60-MINUTE MOCK INTERVIEW',esc(m.title),esc(m.focus))+`<div class="note">Use a separate timer for each segment. Score each round from 0 to 4: <strong>0</strong> missing · <strong>1</strong> major gaps · <strong>2</strong> correct with help · <strong>3</strong> independent and clear · <strong>4</strong> handles tradeoffs and follow-ups. These scores guide practice; they do not predict a hiring decision.</div><div class="article">${m.rounds.map((r,i)=>`<section><div class="inline-meta"><span class="tag">${r.minutes} MIN</span><span>ROUND ${i+1}</span></div><h2>${esc(r.title)}</h2><p><strong>${esc(r.prompt)}</strong></p>${qa('Interviewer guide · follow-ups and answer criteria',`<h4>Follow-up questions</h4><ul>${r.followups.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><h4>What a strong answer covers</h4><p>${esc(r.answer)}</p><ul>${r.rubric.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>${r.hint?'<p><strong>If stuck:</strong> '+esc(r.hint)+'</p>':''}`)}<div class="score-row"><label for="score-${i}">Score for ${esc(r.title)}</label><select id="score-${i}" data-score="${m.id}-${i}"><option value="">Not scored</option>${[0,1,2,3,4].map(n=>`<option value="${n}" ${state.scores[m.id+'-'+i]===String(n)?'selected':''}>${n} / 4</option>`).join('')}</select></div></section>`).join('')}<div class="rubric"><p class="score-total" id="score-total">${mockScore(m)}</p><p>Feedback: name one strength, one specific gap, and one exercise to repeat. Re-run weak segments after a day, without the guide.</p></div>${completion(m.id)}</div>`;}
function mockScore(m){const scored=m.rounds.map((r,i)=>state.scores[m.id+'-'+i]).filter(x=>x!==undefined&&x!=='');return scored.length?`${scored.reduce((s,x)=>s+Number(x),0)} / ${m.rounds.length*4} points · ${scored.length}/${m.rounds.length} rounds scored`:'No rounds scored yet';}
function videos(){return heading('VIDEO SHELF','A second explanation, when you need it.','Start with the written lessons. Use these videos for a concept that has not clicked, then come back and explain it in your own words.')+`<div class="cards">${course.videos.map((v,i)=>`<a class="card video-item" href="${esc(v.url)}" target="_blank" rel="noopener noreferrer"><div class="video-top"><span>${esc(v.topic.toUpperCase())}</span><span class="play" aria-hidden="true">▶</span></div><span class="card-meta">${esc(v.channel)}${i===0?' · YOUR REFERENCE':''}</span><h3 style="margin-top:10px">${esc(v.title)}</h3><p>${esc(v.why)}</p><div class="arrow-link" style="margin-top:20px">Watch on YouTube ↗</div></a>`).join('')}</div><p class="muted" style="margin-top:25px">Video titles and links checked September 2026. Interfaces and example versions in older videos can differ from current tools.</p>`;}
function context(){return heading('INTERVIEW CONTEXT','Prepare with context, not guesses.','The topic priorities come from the shared interview notes. The product context below comes from the public Shownex website.')+`<article class="article"><h2>What the product presents</h2><p>${esc(course.company.summary)}</p><ul>${course.company.verified.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><p><a href="${esc(course.company.sourceUrl)}" target="_blank" rel="noopener noreferrer">Primary source: Shownex ↗</a></p><h2>What we infer for practice</h2><p>${esc(course.company.inference)}</p><h2>How the resume shapes the guide</h2><p>The examples connect to Node.js and TypeScript API ownership, database query optimization, team leadership, incident investigation workflows, inventory idempotency and real-time chess. Use actual evidence from your work; examples in this guide do not establish that you personally implemented a feature.</p><h2>Optional technical references</h2><p>The lessons are designed to stand on their own. These official references are only for checking syntax or exploring a detail.</p><ul>${course.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></li>`).join('')}</ul><p class="muted">Independent study material; not affiliated with Shownex. The resume PDF, phone number, and email address are not part of this public project.</p></article>`;}
function review(){const points=[['Node.js','JavaScript callbacks usually run on one main thread. Async I/O lets work overlap. CPU loops still block. Promise.all does not cancel its siblings.','node-async'],['Redis','Cache-aside: read cache → miss → source → store with TTL. Plan for stale data, hot keys, stampedes and cache failure. Name the source of truth.','redis-reliability'],['AWS jobs','Scheduler starts work; SQS buffers it; workers process it. Expect duplicate delivery. Use atomic idempotency, retry limits and a DLQ with alarms.','aws-jobs'],['RAG','Ingest → chunk → embed → store. Query → embed → retrieve authorized evidence → rerank if useful → generate with citations → evaluate.','rag-pipeline'],['System design','Clarify users, scope, scale and latency. Propose the smallest design. Trace a read, a write and a failure. State consistency and freshness tradeoffs.','system-design'],['DSA','Map for value lookup, Set for membership, two pointers for array/list relationships. State your invariant, trace it, test edges, then complexity.','dsa-maps'],['Your experience','Situation → constraint → your action → evidence → tradeoff → what you learned. Be ready to substantiate 40% and separate personal from team scope.','resume-stories'],['React','Render from props and state. Effects synchronize external systems. Clean up requests; use stable keys. Memoization is a measured optimization.','react-refresh']];return heading('LAST-MINUTE REVIEW','Close the tabs. Open your memory.','Spend 20 minutes answering aloud. When an answer feels vague, revisit that one lesson.')+`<div class="cards">${points.map(([t,p,id])=>`<article class="card"><h3>${t}</h3><p>${p}</p><a href="${lessonUrl(id)}" class="arrow-link">Revisit lesson →</a></article>`).join('')}</div>`+sectionHead('The final ten minutes')+`<div class="article"><ol><li>Give your 90-second introduction and one 3-minute project story.</li><li>Draw cache-aside and explain what happens when Redis fails.</li><li>Draw RAG ingestion and query paths separately.</li><li>Explain a duplicate job and why a simple check-then-write is unsafe.</li><li>Trace Two Sum and reverse a three-node linked list.</li><li>Prepare two questions: “What does this role own in the first 90 days?” and “Which reliability or latency problem is most pressing?”</li></ol><p>During the interview, clarify assumptions, name uncertainty, and narrate your next step. A reasoned tradeoff is stronger than a list of technology names.</p></div>`;}
const demoDocs=[{id:'C1',title:'Moonlight Courier',text:'A gentle science fiction comedy about a courier delivering letters across space. Optimistic friendship, no horror.',tags:'space science fiction gentle funny comedy optimistic friendship',region:'IN'}, {id:'C2',title:'The Last Platform',text:'A tense urban mystery about a missing passenger and a detective. Dark suspense and crime.',tags:'dark tense mystery detective crime suspense thriller',region:'IN'}, {id:'C3',title:'Weekend Table',text:'A warm family comedy about siblings cooking together. Light humor and friendship.',tags:'warm light gentle funny comedy family cooking friendship',region:'US'}, {id:'C4',title:'Red Orbit',text:'An intense science fiction horror story on an isolated space station. Survival and fear.',tags:'space science fiction horror dark tense fear survival',region:'IN'}];
function lab(){return heading('RAG LAB','See the pipeline. Then build it.','A small movie example makes every step visible. First inspect retrieval here, then run the full local Node.js example.')+`<div class="lab-steps"><span class="lab-step">1. Documents</span><span class="lab-step">2. Retrieve</span><span class="lab-step">3. Build context</span><span class="lab-step">4. Answer + sources</span></div><div class="note"><strong>This browser demo is deliberately simple.</strong>It uses keyword overlap and a fixed response template, not embeddings or an LLM. All four movie records are fictional. The downloadable example below makes real local embedding and generation calls.</div><div class="two-col"><section class="card"><h2>Try a question</h2><label for="lab-query">What would you like to watch?</label><form class="lab-form" id="lab-form"><input id="lab-query" value="gentle space comedy" maxlength="200" required><button class="btn" type="submit">Retrieve</button></form><div class="score-row" style="margin-top:15px"><label for="lab-region">Catalog region</label><select id="lab-region"><option value="IN">India</option><option value="US">United States</option></select></div><p class="card-meta">Region is applied before ranking. Try “cooking” in each region, or an unrelated question.</p><div id="lab-output" aria-live="polite"></div></section><section class="card"><h2>The tiny source collection</h2>${demoDocs.map(d=>`<div class="retrieval-result"><h3>[${d.id}] ${d.title} <span class="tag">${d.region}</span></h3><p>${d.text}</p></div>`).join('')}</section></div>`+sectionHead('Run a real end-to-end RAG example')+`<article class="article"><p>This small Node.js command-line project loads a local corpus, chunks it, calls an embedding model, saves vectors to disk, embeds your question, filters by region, ranks by cosine similarity, and asks a local language model to answer with source IDs. It uses no paid API and no browser API key. Model downloads, disk space and a machine capable of running the chosen models are required.</p><h3>Setup</h3><ol><li>Install a supported Node.js version (22 or newer) and <a href="https://ollama.com/download" target="_blank" rel="noopener noreferrer">Ollama</a>. Keep Ollama running locally.</li><li>Download <a href="examples/rag.mjs" download>rag.mjs</a> and <a href="examples/movies.json" download>movies.json</a> into the same folder.</li><li>In that folder, pull the models and run the commands below.</li></ol><pre><code>ollama pull nomic-embed-text
ollama pull llama3.2
node rag.mjs ingest
node rag.mjs ask "gentle space comedy" IN
node rag.mjs ask "cooking with family" US</code></pre><p>The first command creates <code>rag-index.json</code>. Re-ingest whenever you change the corpus or embedding model. The ask command prints retrieved IDs and scores before its answer. Model execution speed depends on your computer. If connection fails, start Ollama; if a model is missing, pull it before retrying.</p>${qa('Read the complete Node.js implementation',`<pre><code>${esc(course.ragCode||'Example loading.')}</code></pre>`)}<h3>What to explain in the interview</h3><ul><li>The embedding model turns text into numeric vectors; cosine similarity ranks direction, not exact word overlap.</li><li>The demo uses a linear scan so the retrieval mechanism is visible. A large collection needs a vector index, ingestion batching and durable storage.</li><li>Region is a business filter. Real private data also needs server-enforced tenant and access filters before retrieval results reach the model.</li><li>Generation can still fabricate or mis-cite. Inspect evidence and evaluate unsupported questions. The code rejects unknown citation IDs, but that alone cannot prove factual support.</li><li>The example abstains when the region has no records. Production relevance thresholds need calibration on labeled queries; nearest does not automatically mean relevant.</li></ul><p class="note">This is an educational local example, not a production service. Its transport and retrieval logic are tested with a stub server; actual model responses depend on your locally installed models.</p><a class="btn" href="#/learn/rag-quality">Learn how to evaluate RAG →</a></article>`;}
function runLab(){const query=$('#lab-query').value.trim();const region=$('#lab-region').value;const words=[...new Set(query.toLowerCase().match(/[a-z]+/g)||[])].filter(w=>!['a','the','and','for','with','i','want','to','watch'].includes(w));const rows=demoDocs.filter(d=>d.region===region).map(d=>({...d,score:words.filter(w=>new Set(d.tags.split(' ')).has(w)).length})).filter(d=>d.score>0).sort((a,b)=>b.score-a.score).slice(0,2);$('#lab-output').innerHTML=`<h3 style="margin-top:25px">${rows.length?'Retrieved evidence':'No supporting evidence'}</h3>`+rows.map(d=>`<div class="retrieval-result"><h3>[${d.id}] ${d.title}</h3><p>${d.score} matching query words · ${d.region}</p><div class="bar"><i style="width:${d.score/Math.max(1,words.length)*100}%"></i></div></div>`).join('')+(rows.length?`<h3>Context sent to the answer step</h3><pre><code>${esc(rows.map(d=>'['+d.id+'] '+d.text).join('\n'))}</code></pre><h3>Template answer</h3><p>One candidate is <strong>${rows[0].title}</strong>: ${esc(rows[0].text)} [${rows[0].id}]</p><p class="card-meta">Word matching does not understand negation or meaning. Try “no horror” to see why semantic retrieval and evaluation matter.</p>`:'<p>I do not have enough evidence in this region. Change the query or inspect the source records.</p>');}
function missing(){return heading('PAGE NOT FOUND','Let’s get back to preparing.','This study page does not exist.')+'<a class="btn" href="#/">Open the study room</a>';}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
function render(){const route=location.hash.replace(/^#/,'')||'/';const parts=route.split('/').filter(Boolean);const root=parts[0]||'';$('#nav').innerHTML=nav.map(([path,icon,label])=>`<a href="#${path}" class="${path===(root?'/'+root:'/')?'active':''}" ${path===(root?'/'+root:'/')?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');const main=$('#main');let html;switch(root){case '':html=home();break;case 'plan':html=plan();break;case 'learn':html=parts[1]==='track'?library(parts[2]):parts[1]?lesson(parts[1]):library();break;case 'practice':html=practice(parts[1]);break;case 'mocks':html=mocks(parts[1]);break;case 'videos':html=videos();break;case 'lab':html=lab();break;case 'review':html=review();break;case 'context':html=context();break;default:html=missing();}main.innerHTML=html;updateProgress();document.title=($('#main h1')?.textContent||'Study room')+' · Interview Studio';if(root==='lab')runLab();if(!storageAvailable)toast('Browser storage is unavailable. Progress will last for this visit.');}
document.addEventListener('click',e=>{const p=e.target.closest('[data-plan]');if(p){state.plan=p.dataset.plan;save();render();return;}const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.done||el.dataset.checks){const type=el.dataset.done?'done':'checks';const id=el.dataset[type];state[type][id]=el.checked;save();updateProgress();document.querySelectorAll(`input[data-${type}="${id}"]`).forEach(x=>x.checked=el.checked);toast(el.checked?'Progress saved. Keep going.':'Marked for another look.');}if(el.dataset.score){state.scores[el.dataset.score]=el.value;save();const id=location.hash.split('/')[2];$('#score-total').textContent=mockScore(course.mocks.find(m=>m.id===id));}if(el.id==='lab-region')runLab();});
document.addEventListener('submit',e=>{if(e.target.id==='lab-form'){e.preventDefault();runLab();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
